CREATE TABLE fulfillments(id UUID PRIMARY KEY,tenant_id UUID NOT NULL,order_id UUID NOT NULL,warehouse_id UUID NOT NULL REFERENCES warehouses(id),status VARCHAR(32) NOT NULL,started_at TIMESTAMP WITH TIME ZONE,completed_at TIMESTAMP WITH TIME ZONE,created_by UUID NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE INDEX idx_fulfillment_tenant_order ON fulfillments(tenant_id,order_id);CREATE INDEX idx_fulfillment_tenant_status ON fulfillments(tenant_id,status);
CREATE TABLE picking_tasks(id UUID PRIMARY KEY,tenant_id UUID NOT NULL,fulfillment_id UUID NOT NULL REFERENCES fulfillments(id),inventory_id UUID NOT NULL REFERENCES inventory(id),quantity NUMERIC(19,4) NOT NULL CHECK(quantity>0),warehouse_location VARCHAR(128) NOT NULL,operator_id UUID NOT NULL,status VARCHAR(32) NOT NULL,picked_at TIMESTAMP WITH TIME ZONE);
CREATE INDEX idx_picking_tenant_fulfillment ON picking_tasks(tenant_id,fulfillment_id);
CREATE TABLE packing_tasks(id UUID PRIMARY KEY,tenant_id UUID NOT NULL,fulfillment_id UUID NOT NULL REFERENCES fulfillments(id),package_number VARCHAR(64) NOT NULL,package_weight NUMERIC(19,4) NOT NULL CHECK(package_weight>0),package_volume NUMERIC(19,4) NOT NULL CHECK(package_volume>0),status VARCHAR(32) NOT NULL,packed_at TIMESTAMP WITH TIME ZONE);
CREATE INDEX idx_packing_tenant_fulfillment ON packing_tasks(tenant_id,fulfillment_id);
